public class CartOrder {
    private final Long orderId;           // required
    private final String customerId;      // required
    private final Double discountPercent; // optional
    private final String couponCode;      // optional
    private final boolean giftWrap;       // optional

    private CartOrder(Builder builder) {
        this.orderId = builder.orderId;
        this.customerId = builder.customerId;
        this.discountPercent = builder.discountPercent;
        this.couponCode = builder.couponCode;
        this.giftWrap = builder.giftWrap;
    }

    public static class Builder {
        private final Long orderId;           // required in constructor
        private final String customerId;      // required in constructor
        private Double discountPercent = 0.0; // optional with default
        private String couponCode = null;
        private boolean giftWrap = false;

        public Builder(Long orderId, String customerId) {
            this.orderId = orderId;
            this.customerId = customerId;
        }

        public Builder discountPercent(Double val) {
            this.discountPercent = val;
            return this;  // enables method chaining
        }

        public Builder couponCode(String val) {
            this.couponCode = val;
            return this;
        }

        public Builder giftWrap(boolean val) {
            this.giftWrap = val;
            return this;
        }

        public CartOrder build() {
            if (discountPercent < 0 || discountPercent > 100) {
                throw new IllegalStateException("Discount must be 0-100");
            }
            return new CartOrder(this);  // single construction point
        }
    }
}

// Usage in service
var order = new CartOrder.Builder(123L, "CUST456")
    .discountPercent(15.0)
    .giftWrap(true)
    .build();

public class ShoppingCart {
    private final String cartId;
    private final String userId;
    private final List<String> items;
    private final String paymentMethod;
    private final boolean expressShipping;

    private ShoppingCart(Builder builder) {  // private constructor
        this.cartId = builder.cartId;
        this.userId = builder.userId;
        this.items = List.copyOf(builder.items);  // defensive copy
        this.paymentMethod = builder.paymentMethod;
        this.expressShipping = builder.expressShipping;
    }

    public static class Builder {  // static nested class
        private final String cartId;      // required
        private final String userId;      // required
        private List<String> items = new ArrayList<>();
        private String paymentMethod = "CREDIT_CARD";
        private boolean expressShipping = false;

        public Builder(String cartId, String userId) {
            if (cartId == null || userId == null) {
                throw new IllegalArgumentException("cartId and userId required");
            }
            this.cartId = cartId;
            this.userId = userId;
        }

        public Builder items(List<String> val) {
            this.items = val;
            return this;  // method chaining
        }

        public Builder paymentMethod(String val) {
            this.paymentMethod = val;
            return this;
        }

        public Builder expressShipping(boolean val) {
            this.expressShipping = val;
            return this;
        }

        public ShoppingCart build() {
            if (items.isEmpty()) {
                throw new IllegalStateException("Cart must have at least one item");
            }
            return new ShoppingCart(this);  // construct outer object
        }
    }
}

// Usage
var cart = new ShoppingCart.Builder("CART123", "USER456")
    .items(List.of("item1", "item2"))
    .expressShipping(true)
    .build();

import lombok.Builder;
import lombok.Getter;
import jakarta.persistence.*;
import java.time.LocalDateTime;

@Entity
@Getter
@Builder(toBuilder = true)  // enables creating modified copies
public class CartItem {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String productId;
    private String productName;
    private Integer quantity;
    private Double unitPrice;

    @Builder.Default  // specify default value
    private LocalDateTime addedAt = LocalDateTime.now();

    @Builder.Default
    private boolean available = true;

    // Lombok generates all of this at compile time:
    // - static inner Builder class
    // - private all-args constructor
    // - productId(String val), productName(String val), etc.
    // - build() method
    // - toBuilder() method for creating modified copies
}

// Usage in service
@Service
public class CartService {
    public CartItem createCartItem(String productId, int quantity) {
        return CartItem.builder()
            .productId(productId)
            .productName("Sample Product")
            .quantity(quantity)
            .unitPrice(29.99)
            .build();  // validation happens here if using @NonNull
    }

    public CartItem increaseQuantity(CartItem item) {
        return item.toBuilder()  // create modified copy
            .quantity(item.getQuantity() + 1)
            .build();
    }
}

import java.time.LocalDateTime;
import java.util.List;

public final class OrderSummary {  // final class prevents subclassing
    private final Long orderId;              // all fields final
    private final String customerId;
    private final List<String> itemIds;
    private final Double totalAmount;
    private final LocalDateTime createdAt;
    private final String couponCode;         // optional, can be null
    private final boolean expressDelivery;   // optional, has default

    private OrderSummary(Builder builder) {
        this.orderId = builder.orderId;
        this.customerId = builder.customerId;
        this.itemIds = List.copyOf(builder.itemIds);  // defensive immutable copy
        this.totalAmount = builder.totalAmount;
        this.createdAt = builder.createdAt;
        this.couponCode = builder.couponCode;
        this.expressDelivery = builder.expressDelivery;
    }

    // Only getters, no setters — true immutability
    public Long getOrderId() { return orderId; }
    public List<String> getItemIds() { return itemIds; }  // already immutable

    public static class Builder {
        private final Long orderId;        // required, final in Builder too
        private final String customerId;
        private List<String> itemIds = List.of();  // mutable during build
        private Double totalAmount = 0.0;
        private LocalDateTime createdAt = LocalDateTime.now();
        private String couponCode;
        private boolean expressDelivery = false;

        public Builder(Long orderId, String customerId) {
            this.orderId = orderId;
            this.customerId = customerId;
        }

        public Builder itemIds(List<String> val) {
            this.itemIds = val;  // Builder is mutable
            return this;
        }

        public Builder totalAmount(Double val) {
            this.totalAmount = val;
            return this;
        }

        public Builder couponCode(String val) {
            this.couponCode = val;
            return this;
        }

        public OrderSummary build() {
            return new OrderSummary(this);  // atomic immutable object creation
        }
    }
}

import java.util.ArrayList;
import java.util.List;

public class ProductOrder {
    private final String orderId;      // required
    private final String customerId;   // required
    private final List<String> items;  // required (must not be empty)
    private final Double discount;     // optional
    private final String promoCode;    // optional
    private final boolean priority;    // optional

    private ProductOrder(Builder builder) {
        this.orderId = builder.orderId;
        this.customerId = builder.customerId;
        this.items = List.copyOf(builder.items);
        this.discount = builder.discount;
        this.promoCode = builder.promoCode;
        this.priority = builder.priority;
    }

    public static class Builder {
        // Required fields: final, set in constructor
        private final String orderId;
        private final String customerId;
        private final List<String> items;

        // Optional fields: mutable, with defaults
        private Double discount = 0.0;
        private String promoCode = null;
        private boolean priority = false;

        // Constructor enforces required fields at compile time
        public Builder(String orderId, String customerId, List<String> items) {
            if (orderId == null || customerId == null) {
                throw new IllegalArgumentException("orderId and customerId required");
            }
            this.orderId = orderId;
            this.customerId = customerId;
            this.items = new ArrayList<>(items);  // defensive copy
        }

        public Builder discount(Double val) {
            this.discount = val;
            return this;
        }

        public Builder promoCode(String val) {
            this.promoCode = val;
            return this;
        }

        public Builder priority(boolean val) {
            this.priority = val;
            return this;
        }

        public ProductOrder build() {
            // Validation: business rules beyond null checks
            if (items.isEmpty()) {
                throw new IllegalStateException("Order must contain at least one item");
            }
            if (discount < 0.0 || discount > 100.0) {
                throw new IllegalStateException("Discount must be between 0 and 100");
            }
            if (promoCode != null && promoCode.isBlank()) {
                throw new IllegalStateException("Promo code cannot be blank");
            }
            return new ProductOrder(this);
        }
    }
}

public class UserProfile {
    private final String username;
    private final String email;
    private final String displayName;
    private final Integer age;
    private final String city;

    private UserProfile(Builder builder) {
        this.username = builder.username;
        this.email = builder.email;
        this.displayName = builder.displayName;
        this.age = builder.age;
        this.city = builder.city;
    }

    public static class Builder {
        private final String username;
        private final String email;
        private String displayName;
        private Integer age;
        private String city;

        public Builder(String username, String email) {
            this.username = username;
            this.email = email;
        }

        // Each setter returns 'this' — enables chaining
        public Builder displayName(String val) {
            this.displayName = val;
            return this;  // critical for chaining
        }

        public Builder age(Integer val) {
            this.age = val;
            return this;
        }

        public Builder city(String val) {
            this.city = val;
            return this;
        }

        public UserProfile build() {
            return new UserProfile(this);
        }
    }
}

// Usage: fluent chaining in a single expression
var profile = new UserProfile.Builder("alice", "alice@example.com")
    .displayName("Alice Smith")  // returns Builder
    .age(28)                     // returns Builder
    .city("San Francisco")       // returns Builder
    .build();                    // returns UserProfile

// Common in test fixtures — highly readable
var testUser = new UserProfile.Builder("testuser", "test@test.com")
    .displayName("Test User")
    .age(30)
    .build();
